"""Rebuild constraints.txt after you change a version in requirements.txt.

It installs the requirements into a temporary virtual environment and records
the exact version of every package, so that everyone gets the same set.

    python scripts/refresh_constraints.py
"""

from __future__ import annotations

import subprocess
import sys
import tempfile
import venv
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
HEADER = """\
# Exact versions of every package, generated by scripts/refresh_constraints.py.
# Do not edit by hand. Change requirements.txt, then run the script again.
"""


def main() -> int:
    with tempfile.TemporaryDirectory() as folder:
        print("Creating a temporary virtual environment...")
        venv.create(folder, with_pip=True)
        bin_folder = "Scripts" if sys.platform == "win32" else "bin"
        python = str(Path(folder) / bin_folder / "python")
        install = [python, "-m", "pip", "install", "--quiet", "--upgrade", "pip"]
        subprocess.run(install, check=True)  # noqa: S603
        print("Installing requirements.txt and requirements-dev.txt...")
        subprocess.run(  # noqa: S603
            [python, "-m", "pip", "install", "--quiet"]
            + ["-r", str(ROOT / "requirements.txt")]
            + ["-r", str(ROOT / "requirements-dev.txt")],
            check=True,
        )
        frozen = subprocess.run(  # noqa: S603
            [python, "-m", "pip", "freeze", "--exclude-editable"],
            check=True,
            capture_output=True,
            text=True,
        ).stdout
    (ROOT / "constraints.txt").write_text(HEADER + frozen, encoding="utf-8", newline="\n")
    print(f"Wrote constraints.txt with {len(frozen.splitlines())} packages.")
    print("Now run the tests: python -m pytest")
    return 0


if __name__ == "__main__":
    sys.exit(main())
